import{ht as e,nt as t,o as n,tt as r}from"./chunks/framework.BDx6F-5s.js";var i=JSON.parse(`{"title":"AI Specifications","description":"Compare AI test automation methods and the latest tools. Learn how to increase QA efficiency with machine learning-based automated testing.","frontmatter":{"title":"AI Specifications","description":"Compare AI test automation methods and the latest tools. Learn how to increase QA efficiency with machine learning-based automated testing.","head":[["meta",{"name":"keywords","content":"Test Automation, Testing Generative AI, Playwright, Selenium, Real-time Quality Feedback, Zero-downtime Testing, AI-based Test Automation, Continuous Testing, QAOps, TestOps, Codeless, Low-Code, Self-healing Test, Self-healing, AI Test Automation, Codeless Automation, QA Automation, Software Testing, Test Scenario Creation, Codeless Test, Natural Language Test, Test Automation Tool, Test Automation Platform, Test Efficiency, Playwright, Selenium, QAOps, TestOps, Shift-Left Testing, Shift-Right Testing"}],["meta",{"property":"og:title","content":"AI Test Automation | SyncETA"}],["meta",{"property":"og:description","content":"Reduce QA time by 80% with AI-based test automation. Set a new standard for QA with codeless test creation, natural language scenario writing, and multi-platform support."}],["meta",{"property":"og:image","content":"https://empasy.io/docs/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/synceta/"}],["link",{"rel":"canonical","href":"https://empasy.io/docs/en/synceta/spec_ai.html"}]],"sort":3000},"headers":[],"relativePath":"en/synceta/spec_ai.md","filePath":"en/synceta/spec_ai.md","lastUpdated":1787438897000}`),a={name:`en/synceta/spec_ai.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="synceta-test-case-generation-and-learning-module-detailed-specifications" tabindex="-1">SyncETA Test Case Generation and Learning Module Detailed Specifications <a class="header-anchor" href="#synceta-test-case-generation-and-learning-module-detailed-specifications" aria-label="Permalink to “SyncETA Test Case Generation and Learning Module Detailed Specifications”">​</a></h1><p>This document details the hardware and software specifications focusing on natural language-based test case generation using a Large Language Model (LLM), LLM learning through QA feedback, and its quality improvement among SyncETA&#39;s regression test automation solutions.</p><h2 id="_1-system-overview-focusing-on-test-case-generation-and-learning" tabindex="-1">1. System Overview (Focusing on Test Case Generation and Learning) <a class="header-anchor" href="#_1-system-overview-focusing-on-test-case-generation-and-learning" aria-label="Permalink to “1. System Overview (Focusing on Test Case Generation and Learning)”">​</a></h2><p>SyncETA automates scenarios through user browser action recording based on Selenium and converts them into Excel-format test cases with LLM-based natural language processing technology. The generated test cases undergo a verification and modification process by QA engineers, and QA&#39;s feedback is reflected in the LLM&#39;s learning to continuously improve the quality of test case generation. Ultimately, it aims to maximize QA work efficiency and software quality.</p><h2 id="_2-software-detailed-specifications" tabindex="-1">2. Software Detailed Specifications <a class="header-anchor" href="#_2-software-detailed-specifications" aria-label="Permalink to “2. Software Detailed Specifications”">​</a></h2><p>The key software modules related to SyncETA&#39;s test case generation and learning are as follows.</p><h3 id="_2-1-testcase-generator-natural-language-test-case-auto-generation-module" tabindex="-1">2.1. TestCase Generator (Natural Language Test Case Auto-Generation Module) <a class="header-anchor" href="#_2-1-testcase-generator-natural-language-test-case-auto-generation-module" aria-label="Permalink to “2.1. TestCase Generator (Natural Language Test Case Auto-Generation Module)”">​</a></h3><p><strong>Technology</strong>: Utilizes open-source LLMs.</p><p><strong>Input</strong>: Receives JSON format test scenario data generated by the SyncETA Recorder.</p><p><strong>Output</strong>:</p><ul><li>The LLM analyzes the input JSON scenario and automatically generates a natural language-based Excel test case including Step, Input, Expected Result, etc.</li><li>The generated Excel test cases can be provided in the form of reusable templates.</li></ul><p><strong>Key Features and Learning</strong>:</p><ul><li>Context learning about in-house terminology and UI elements is possible. Through this, the LLM can understand unique expressions of specific business domains or services and reflect them in test case generation.</li><li>Supports format customizing tailored to QA standards. This enables flexible test case output that fits the QA team&#39;s existing workflow and report formats.</li><li>Automatically writes test objectives, steps, and expected results in a structured format.</li></ul><h3 id="_2-2-qa-feedback-loop-quality-improvement-loop-module" tabindex="-1">2.2. QA Feedback Loop (Quality Improvement Loop Module) <a class="header-anchor" href="#_2-2-qa-feedback-loop-quality-improvement-loop-module" aria-label="Permalink to “2.2. QA Feedback Loop (Quality Improvement Loop Module)”">​</a></h3><p><strong>Features</strong>:</p><ul><li>QA engineers can directly review and modify Excel test cases generated through the TestCase Generator.</li><li>Optimization tasks such as supplementing incomplete cases, removing duplicate cases, and prioritizing are possible.</li><li>Data modified or evaluated by QA is uploaded to the SyncETA system.</li></ul><p><strong>Learning Reflection and Quality Improvement Loop</strong>:</p><ul><li>Uploaded QA modification data is reflected in the LLM&#39;s re-training (Fine-tuning or RAG, Retrieval-Augmented Generation). Test case generation quality improves through this continuous learning process.</li><li>Secures LLM training data based on QA&#39;s modifications and continuously improves test case generation accuracy and coverage through periodic re-training.</li><li>Over time, the reliability of auto-generated test cases increases and test coverage improves.</li><li>You can monitor the learning effect by providing QA feedback history analysis and improvement history tracking features.</li></ul><h3 id="_2-3-dataset-management-feature-ai-utilization-part" tabindex="-1">2.3. Dataset Management Feature (AI Utilization Part) <a class="header-anchor" href="#_2-3-dataset-management-feature-ai-utilization-part" aria-label="Permalink to “2.3. Dataset Management Feature (AI Utilization Part)”">​</a></h3><p><strong>Features</strong>:</p><ul><li>Can input and manage data in a tabular format, supporting the addition, modification, and deletion of variables.</li><li>You can write directly by calling variable values set in the scenario, and automatically generate mockup data using AI to conduct tests with various values. This feature is for AI to generate data to be used in the test, which is separate from the AI generation of the test case itself.</li></ul><h2 id="_3-hardware-detailed-specifications-related-to-llm-operation" tabindex="-1">3. Hardware Detailed Specifications (Related to LLM Operation) <a class="header-anchor" href="#_3-hardware-detailed-specifications-related-to-llm-operation" aria-label="Permalink to “3. Hardware Detailed Specifications (Related to LLM Operation)”">​</a></h2><p>SyncETA supports the following deployment environments for the flexible operation of LLM models.</p><p><strong>Deployment Format</strong>: SyncETA can be deployed as a Docker-based installation (On-premise) or as a Cloud SaaS (Software as a Service) format.</p><p><strong>Security Requirements</strong>: Depending on security requirements, it supports executing LLM models directly in an On-premise environment. This can strengthen security by lowering dependence on external cloud LLM services when processing sensitive data.</p><h2 id="_4-expected-effects-related-to-test-case-generation-and-learning" tabindex="-1">4. Expected Effects (Related to Test Case Generation and Learning) <a class="header-anchor" href="#_4-expected-effects-related-to-test-case-generation-and-learning" aria-label="Permalink to “4. Expected Effects (Related to Test Case Generation and Learning)”">​</a></h2><p>SyncETA&#39;s test case generation and learning features provide the following key expected effects:</p><ul><li><strong>Reduce test case writing time by 80%</strong>: Drastically shortens test case writing time compared to manual work through Selenium recording and LLM-based automatic generation.</li><li><strong>Streamline QA Resources</strong>: Repetitive test case writing tasks are automated through AI-based test case generation and the QA feedback loop, increasing QA work efficiency and reducing QA resources by more than 30%. QA personnel can save time by focusing on verifying automatically generated cases.</li><li><strong>Improve Test Quality and Reliability</strong>: Through AI-based test case generation and the QA feedback loop, test accuracy and coverage improve, preventing human errors and maintaining consistent quality. Test coverage is improved by the LLM&#39;s intelligent case generation.</li><li><strong>Test Automation without Writing Code</strong>: Uses an intuitive GUI and keyword-based non-code methods, allowing users lacking development knowledge (QA teams) to easily build test automation. In particular, accessibility is high as natural language-based test cases can be generated through LLMs.</li><li><strong>Continuous Quality Improvement</strong>: Continuously improves test case generation quality by training the LLM with QA feedback data, providing a more accurate and reliable test automation environment.</li></ul>`,28)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};